function Get-IRProcessAnomalies {
    param(
        [string]$ComputerName = $env:COMPUTERNAME,
        [int]$ThresholdCPU = 80
    )
    $procs = Get-Process -ComputerName $ComputerName -ErrorAction SilentlyContinue
    $results = foreach ($p in $procs) {
        $parent = Get-WmiObject Win32_Process -Filter "ProcessId=$($p.Id)" -ComputerName $ComputerName | Select-Object -ExpandProperty ParentProcessId
        $parentName = (Get-Process -Id $parent -ComputerName $ComputerName -ErrorAction SilentlyContinue).Name
        $sig = (Get-AuthenticodeSignature -FilePath $p.Path -ErrorAction SilentlyContinue).Status
        $isAnomalous = ($p.CPU -gt $ThresholdCPU) -or ($sig -ne 'Valid') -or ($parentName -eq 'services.exe' -and $p.Name -ne 'svchost.exe') -or ($p.SessionId -ne 0 -and $p.Name -match 'csrss|wininit|smss')
        if ($isAnomalous) {
            [PSCustomObject]@{
                Computer   = $ComputerName
                PID        = $p.Id
                Name       = $p.Name
                Path       = $p.Path
                Parent     = "$parentName ($parent)"
                Signature  = $sig
                CPU_Pct    = [math]::Round($p.CPU,2)
                Flags      = "AnomalyDetected"
            }
        }
    }
    Write-SysLog "IR: ProcessAnomalies scan completed on $ComputerName. Found: $($results.Count)"
    return $results
}

function Block-IRIOC_Network {
    param(
        [string[]]$IPList,
        [string]$RuleNamePrefix = 'IR_BLOCK_',
        [ValidateSet('In','Out','Both')][string]$Direction = 'Both'
    )
    try {
        foreach ($ip in $IPList) {
            $dir = if ($Direction -eq 'Both') { 'In,Out' } else { $Direction }
            New-NetFirewallRule -DisplayName "$RuleNamePrefix$ip" -Direction $dir -Action Block -RemoteAddress $ip -Enabled True -ErrorAction Stop
        }
        Write-SysLog "IR: $(($IPList).Count) firewall rules applied."
        return $true
    } catch {
        Write-SysLog "IR: Firewall rule creation failed: $_" -Level 'ERROR'
        return $false
    }
}

function Isolate-IRHost_Net {
    param(
        [string[]]$ExcludeIPs = @(),
        [switch]$DisableAdapters
    )
    try {
        if ($DisableAdapters) {
            Get-NetAdapter | Where-Object Status -eq 'Up' | Disable-NetAdapter -Confirm:$false -ErrorAction SilentlyContinue
            Write-SysLog "IR: Network adapters disabled for isolation."
        } else {
            $ruleName = 'IR_NETWORK_ISOLATION'
            Remove-NetFirewallRule -DisplayName $ruleName -ErrorAction SilentlyContinue
            New-NetFirewallRule -DisplayName $ruleName -Direction Outbound -Action Block -RemoteAddress 'Any' -ErrorAction Stop
            foreach ($ip in $ExcludeIPs) {
                New-NetFirewallRule -DisplayName "IR_ALLOW_$ip" -Direction Outbound -Action Allow -RemoteAddress $ip -ErrorAction Stop
            }
            Write-SysLog "IR: Network isolation applied. Exceptions: $($ExcludeIPs -join ',')"
        }
    } catch {
        Write-SysLog "IR: Isolation failed: $_" -Level 'ERROR'
        throw
    }
}

function Get-IRPersistenceScan {
    param([string]$ComputerName = $env:COMPUTERNAME)
    $out = @()
    # Run Keys
    $keys = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run', 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run')
    foreach ($k in $keys) { if (Test-Path $k) { Get-ItemProperty $k | Select-Object * | ForEach-Object { $out += [PSCustomObject]@{Type='Registry'; Key=$k; Data=$_.PSObject.Properties | Where-Object Name -ne 'PSPath' | ForEach-Object { "$($_.Name)=$($_.Value)" }}} }}
    # Tasks
    $out += Get-ScheduledTask -ComputerName $ComputerName -ErrorAction SilentlyContinue | Where-Object { $_.State -eq 'Ready' -or $_.State -eq 'Running' } | ForEach-Object { [PSCustomObject]@{Type='Task'; Name=$_.TaskName; State=$_.State; Actions=($_.Actions.Execute -join ',')} }
    # Services
    $out += Get-Service -ComputerName $ComputerName -ErrorAction SilentlyContinue | Where-Object { $_.StartType -eq 'Auto' -and $_.Status -eq 'Running' } | ForEach-Object { [PSCustomObject]@{Type='Service'; Name=$_.Name; DisplayName=$_.DisplayName; Path=(Get-CimInstance Win32_Service -Filter "Name='$($_.Name)'").PathName} }
    Write-SysLog "IR: Persistence scan completed. Items: $($out.Count)"
    return $out
}

using System;
using System.Diagnostics;
using System.Runtime.InteropServices;

public static int KillProcessTree(int PID, bool ForceKill = true)
{
    int killed = 0;
    Process proc = Process.GetProcessById(PID);
    foreach (Process child in GetChildProcesses(PID))
    {
        try { if (ForceKill) child.Kill(); else child.CloseMainWindow(); killed++; }
        catch { /* Ignore access denied */ }
    }
    try { if (ForceKill) proc.Kill(); else proc.CloseMainWindow(); killed++; }
    catch { /* Ignore */ }
    return killed;
}

private static Process[] GetChildProcesses(int parentPID)
{
    using (ManagementObjectSearcher mos = new ManagementObjectSearcher("SELECT ProcessId FROM Win32_Process WHERE ParentProcessId = " + parentPID))
    {
        return mos.Get().Cast<ManagementObject>().Select(mo => Process.GetProcessById((int)mo["ProcessId"])).ToArray();
    }
}

using System;
using System.IO;
using System.Security.Cryptography;

public static bool ScanFileIntegrity(string FilePath, string KnownHash = null)
{
    if (!File.Exists(FilePath)) throw new FileNotFoundException();
    using (var sha = SHA256.Create())
    using (var stream = File.OpenRead(FilePath))
    {
        var hash = sha.ComputeHash(stream);
        string computed = BitConverter.ToString(hash).Replace("-", "").ToLower();
        Console.WriteLine($"[SHA256] {FilePath} -> {computed}");
        if (!string.IsNullOrEmpty(KnownHash))
        {
            bool match = computed.Equals(KnownHash, StringComparison.OrdinalIgnoreCase);
            if (!match) Console.WriteLine($"[ALERT] Hash mismatch on {FilePath}");
            return match;
        }
        return true;
    }
}

using Microsoft.Win32;

public static void ProtectIRLSASS(bool EnablePPL = true, bool AuditOnly = false)
{
    const string path = @"HKLM:\SYSTEM\CurrentControlSet\Control\Lsa";
    string runAsPpl = AuditOnly ? "2" : (EnablePPL ? "1" : "0");
    Registry.SetValue(path, "RunAsPPL", runAsPpl, RegistryValueKind.DWord);

    // Defender ASR Rule: Block credential stealing from Windows LSASS
    string asrGuid = "9e6c4e1f-7d60-472f-ba1b-a3d2b8e27f84";
    Registry.SetValue(@"HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender\Windows Defender Exploit Guard\ASR\Rules", asrGuid, AuditOnly ? "2" : "1");

    Console.WriteLine($"[IR] LSASS Protection applied. PPL={runAsPpl}, ASR={(AuditOnly ? "Audit" : "Block")}");
}

using System;
using System.Diagnostics;

public static bool DisableIRNetworkAdapter(string AdapterName)
{
    try
    {
        Process.Start(new ProcessStartInfo
        {
            FileName = "netsh",
            Arguments = $"interface set interface \"{AdapterName}\" disable",
            WindowStyle = ProcessWindowStyle.Hidden,
            UseShellExecute = false
        }).WaitForExit();
        Console.WriteLine($"[IR] Adapter {AdapterName} disabled.");
        return true;
    }
    catch (Exception ex)
    {
        Console.WriteLine($"[IR] Failed to disable adapter: {ex.Message}");
        return false;
    }
}

using System;
using System.Net.NetworkInformation;
using System.Net;
using System.Linq;

public static object[] QueryIRRawSockets(bool IncludeEstablished = true)
{
    var tcp = IPGlobalProperties.GetIPGlobalProperties().GetActiveTcpConnections();
    var conns = tcp.Where(c => IncludeEstablished || c.State != TcpState.Established)
                   .Select(c => new { Local = c.LocalEndPoint.ToString(), Remote = c.RemoteEndPoint.ToString(), State = c.State.ToString(), PID = "N/A (Use Get-NetTCPConnection)" })
                   .ToArray();
    Console.WriteLine($"[IR] Raw sockets queried: {conns.Length} connections");
    return conns;
}
